/**
 * Deterministic id for the transaction generated by one occurrence of a
 * recurring rule. Two tabs or devices processing the same due date produce the
 * same id, so the server upsert collapses them into a single row instead of
 * creating duplicates.
 */
export function buildRecurringOccurrenceId(recurringId: string, nextDue: string): string {
  return `rec:${recurringId}:${nextDue.slice(0, 10)}`;
}
